package local.ondemand;
import android.view.*;import android.widget.*;import org.json.*;
final class PosterCard {
 static int columns(MainActivity a){int available=a.getResources().getDisplayMetrics().widthPixels-a.dp(40),height=a.getResources().getDisplayMetrics().heightPixels;int target=Math.max(a.dp(120),(height-a.dp(140))/2);int width=(target-a.dp(34))*2/3;return Math.max(5,(int)Math.ceil((available+a.dp(8))/(double)(width+a.dp(8))));}
 static int width(MainActivity a){int columns=columns(a);return (a.getResources().getDisplayMetrics().widthPixels-a.dp(40)-a.dp(8)*(columns-1))/columns;}
 static int height(MainActivity a){return width(a)*3/2+a.dp(34);}
 static View create(MainActivity a,JSONObject m,String tag,Runnable click){LinearLayout card=new LinearLayout(a);card.setId(View.generateViewId());card.setTag(tag);card.setOrientation(1);card.setFocusable(true);card.setClickable(true);card.setDescendantFocusability(ViewGroup.FOCUS_BLOCK_DESCENDANTS);card.setPadding(a.dp(3),a.dp(3),a.dp(3),a.dp(3));card.setBackground(a.shape(0xff151515,0,7));card.setOnFocusChangeListener((v,f)->{android.graphics.drawable.GradientDrawable g=a.shape(f?0xff242424:0xff151515,f?0xffffffff:0,7);g.setStroke(a.dp(f?2:1),f?0xffffffff:0xff444444);v.setBackground(g);if(String.valueOf(v.getTag()).startsWith("home:")){v.animate().scaleX(f?1.035f:1f).scaleY(f?1.035f:1f).setDuration(110).start();v.setElevation(f?a.dp(3):0);}});ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackgroundColor(0xff242733);card.addView(image,new LinearLayout.LayoutParams(-1,0,1));TextView name=a.text((!tag.contains(":series:")&&WatchLibrary.watched(a,m.optString("id"))?"✓ ":"")+m.optString("name"),12);name.setSingleLine();name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(a.dp(3),a.dp(3),0,0);card.addView(name);TextView year=a.text(m.optString("releaseInfo",m.optString("type").equals("series")?"Series":"Movie"),10);year.setTextColor(0xffb8c2cc);year.setSingleLine();year.setPadding(a.dp(3),0,0,0);card.addView(year);card.setContentDescription(m.optString("name")+" · "+m.optString("releaseInfo"));card.setOnClickListener(v->click.run());if(!tag.contains(":series:"))card.setOnLongClickListener(v->{TitlePages.watchedMenu(a,m.optString("id"),()->name.setText((WatchLibrary.watched(a,m.optString("id"))?"✓ ":"")+m.optString("name")));return true;});a.poster(image,m.optString("poster"),a.generation);return card;}
}
